package com.learn.hub.ai;

import java.util.List;

import org.springframework.ai.chat.client.ChatClient;
import org.springframework.ai.vectorstore.SearchRequest;
import org.springframework.ai.vectorstore.VectorStore;
import org.springframework.stereotype.Service;

@Service
public class RagAnswerService {

    private final ChatClient chatClient;
    private final VectorStore vectorStore;

    public RagAnswerService(ChatClient.Builder builder, VectorStore vectorStore) {
        this.chatClient = builder
                .defaultSystem("你只根据资料回答，资料不足就说「资料中没有」。")
                .build();
        this.vectorStore = vectorStore;
    }

    public Answer ask(String question, String topicSlug) {
        SearchRequest request = SearchRequest.builder()
                .query(question)
                .topK(5)
                .similarityThreshold(0.65)
                .filter("topic == '" + topicSlug + "'")
                .build();
        String context = vectorStore.similaritySearch(request).stream()
                .map(hit -> "[" + hit.getMetadata().get("chunk_no") + "] " + hit.getText())
                .reduce("", (a, b) -> a + "\n---\n" + b);

        return chatClient.prompt()
                .user(spec -> spec.text("资料：\n{context}\n\n问题：{question}")
                        .param("context", context)
                        .param("question", question))
                .call()
                .entity(Answer.class);
    }

    public record Answer(String conclusion, List<String> citations, double confidence) {
    }
}
